49	func (s *APIV1Service) ListShortcuts(ctx context.Context, request *v1pb.ListShortcutsRequest) (*v1pb.ListShortcutsResponse, error) {
50		user, err := ResolveUserByName(ctx, s.Store, request.Parent)
51		if err != nil {
52			return nil, status.Errorf(codes.InvalidArgument, "invalid user name: %v", err)
53		}
54		if user == nil {
55			return nil, status.Errorf(codes.NotFound, "user not found")
56		}
57		userID := user.ID
58	
59		currentUser, err := s.fetchCurrentUser(ctx)
60		if err != nil {
61			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
62		}
63		if currentUser == nil || currentUser.ID != userID {
64			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
65		}
66	
67		userSetting, err := s.Store.GetUserSetting(ctx, &store.FindUserSetting{
68			UserID: &userID,
69			Key:    storepb.UserSetting_SHORTCUTS,
70		})
71		if err != nil {
72			return nil, status.Errorf(codes.Internal, "failed to get user setting: %v", err)
73		}
74		if userSetting == nil {
75			return &v1pb.ListShortcutsResponse{
76				Shortcuts: []*v1pb.Shortcut{},
77			}, nil
78		}
79	
80		shortcutsUserSetting := userSetting.GetShortcuts()
81		shortcuts := []*v1pb.Shortcut{}
82		for _, shortcut := range shortcutsUserSetting.GetShortcuts() {
83			shortcuts = append(shortcuts, &v1pb.Shortcut{
84				Name:   constructShortcutName(user.Username, shortcut.GetId()),
85				Title:  shortcut.GetTitle(),
86				Filter: shortcut.GetFilter(),
87			})
88		}
89	
90		return &v1pb.ListShortcutsResponse{
91			Shortcuts: shortcuts,
92		}, nil
93	}
