10	type renderer struct {
11		schema             Schema
12		dialect            DialectName
13		placeholderOffset  int
14		placeholderCounter int
15		args               []any
16	}
17	
18	type renderResult struct {
19		sql           string
20		trivial       bool
21		unsatisfiable bool
22	}
23	
24	func newRenderer(schema Schema, opts RenderOptions) *renderer {
25		return &renderer{
26			schema:            schema,
27			dialect:           opts.Dialect,
28			placeholderOffset: opts.PlaceholderOffset,
29		}
30	}
31	
32	func (r *renderer) Render(cond Condition) (Statement, error) {
33		result, err := r.renderCondition(cond)
34		if err != nil {
35			return Statement{}, err
36		}
37		args := r.args
38		if args == nil {
39			args = []any{}
40		}
41	
42		switch {
43		case result.unsatisfiable:
44			return Statement{
45				SQL:  "1 = 0",
46				Args: args,
47			}, nil
48		case result.trivial:
49			return Statement{
50				SQL:  "",
51				Args: args,
52			}, nil
53		default:
54			return Statement{
55				SQL:  result.sql,
56				Args: args,
57			}, nil
58		}
59	}
60	
61	func (r *renderer) renderCondition(cond Condition) (renderResult, error) {
62		switch c := cond.(type) {
63		case *LogicalCondition:
64			return r.renderLogicalCondition(c)
65		case *NotCondition:
66			return r.renderNotCondition(c)
67		case *FieldPredicateCondition:
68			return r.renderFieldPredicate(c)
69		case *ComparisonCondition:
70			return r.renderComparison(c)
71		case *InCondition:
72			return r.renderInCondition(c)
73		case *ElementInCondition:
74			return r.renderElementInCondition(c)
75		case *TextMatchCondition:
76			return r.renderTextMatch(c)
77		case *RegexCondition:
78			return r.renderRegex(c)
79		case *ListComprehensionCondition:
80			return r.renderListComprehension(c)
81		case *ConstantCondition:
82			if c.Value {
83				return renderResult{trivial: true}, nil
84			}
85			return renderResult{sql: "1 = 0", unsatisfiable: true}, nil
86		default:
87			return renderResult{}, errors.Errorf("unsupported condition type %T", c)
88		}
89	}
90	
91	func (r *renderer) renderLogicalCondition(cond *LogicalCondition) (renderResult, error) {
92		left, err := r.renderCondition(cond.Left)
93		if err != nil {
94			return renderResult{}, err
95		}
96		right, err := r.renderCondition(cond.Right)
97		if err != nil {
98			return renderResult{}, err
99		}
100	
101		switch cond.Operator {
102		case LogicalAnd:
103			return combineAnd(left, right), nil
104		case LogicalOr:
105			return combineOr(left, right), nil
106		default:
107			return renderResult{}, errors.Errorf("unsupported logical operator %s", cond.Operator)
108		}
109	}
110	
111	func (r *renderer) renderNotCondition(cond *NotCondition) (renderResult, error) {
112		child, err := r.renderCondition(cond.Expr)
113		if err != nil {
114			return renderResult{}, err
115		}
116	
117		if child.trivial {
118			return renderResult{sql: "1 = 0", unsatisfiable: true}, nil
119		}
120		if child.unsatisfiable {
121			return renderResult{trivial: true}, nil
122		}
123		return renderResult{
124			sql: fmt.Sprintf("NOT (%s)", child.sql),
125		}, nil
126	}
127	
128	func (r *renderer) renderFieldPredicate(cond *FieldPredicateCondition) (renderResult, error) {
129		field, ok := r.schema.Field(cond.Field)
130		if !ok {
131			return renderResult{}, errors.Errorf("unknown field %q", cond.Field)
132		}
133	
134		switch field.Kind {
135		case FieldKindBoolColumn:
136			column := qualifyColumn(r.dialect, field.Column)
137			return renderResult{
138				sql: fmt.Sprintf("%s IS TRUE", column),
139			}, nil
140		case FieldKindJSONBool:
141			sql, err := r.jsonBoolPredicate(field)
142			if err != nil {
143				return renderResult{}, err
144			}
145			return renderResult{sql: sql}, nil
146		default:
147			return renderResult{}, errors.Errorf("field %q cannot be used as a predicate", cond.Field)
148		}
149	}
150	
151	func (r *renderer) renderComparison(cond *ComparisonCondition) (renderResult, error) {
152		switch left := cond.Left.(type) {
153		case *FieldRef:
154			field, ok := r.schema.Field(left.Name)
155			if !ok {
156				return renderResult{}, errors.Errorf("unknown field %q", left.Name)
157			}
158			switch field.Kind {
159			case FieldKindBoolColumn:
160				return r.renderBoolColumnComparison(field, cond.Operator, cond.Right)
161			case FieldKindJSONBool:
162				return r.renderJSONBoolComparison(field, cond.Operator, cond.Right)
163			case FieldKindScalar:
164				return r.renderScalarComparison(field, cond.Operator, cond.Right)
165			default:
166				return renderResult{}, errors.Errorf("field %q does not support comparison", field.Name)
167			}
168		case *FunctionValue:
169			return r.renderFunctionComparison(left, cond.Operator, cond.Right)
170		case *FieldAccessorValue:
171			return r.renderAccessorComparison(left, cond.Operator, cond.Right)
172		default:
173			return renderResult{}, errors.New("comparison must start with a field reference or supported function")
174		}
175	}
